import{_ as i,C as t,o,c as n,E as s,a2 as l}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/continuity-20260914/terminal-result.figure.en.png",w=JSON.parse('{"title":"How Did an Opening Remark Become the Deliverable?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"How Did an Opening Remark Become the Deliverable?","date":"2026-09-14","published_date":"2026-09-14","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"How Did an Opening Remark Become the Deliverable?","summary":"The AI said it would get started. How did that become the finished result? A controlled comparison traces a misleading success signal.","cover":"/assets/continuity-20260914/terminal-result.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments on pinned sources; no live cloud validation","pageClass":"continuity-contracts-article"},"headers":[],"relativePath":"en/engineering/2026-09-14-terminal-result.md","filePath":"en/engineering/2026-09-14-terminal-result.md","lastUpdated":1789364063000}'),c={name:"en/engineering/2026-09-14-terminal-result.md"};function h(u,e,p,m,f,g){const a=t("ArticleCover"),r=t("ArticleTableScroll");return o(),n("div",null,[s(a,{image:"/assets/continuity-20260914/terminal-result.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"How Did an Opening Remark Become the Deliverable?",summary:"The AI said it would get started. How did that become the finished result? A controlled comparison traces a misleading success signal.",version:"2026-09-14",languageHref:"/zh/engineering/2026-09-14-terminal-result",languageLabel:"中文"}),s(r,{language:"en"}),e[0]||(e[0]=l('<h1 id="how-did-an-opening-remark-become-the-deliverable" tabindex="-1">How Did an Opening Remark Become the Deliverable? <a class="header-anchor" href="#how-did-an-opening-remark-become-the-deliverable" aria-label="Permalink to &quot;How Did an Opening Remark Become the Deliverable?&quot;">​</a></h1><p>“I&#39;ll take a look.”</p><p>If a colleague replied with that sentence, you would probably keep waiting. Yet in a fault reported by an open-source AI dispatch project, this kind of opening text ended up in a result file, ready to be treated as the deliverable.</p><p>More surprisingly, the AI service had already reported an error. The program collecting the result trusted another signal: a normal process exit.</p><p>The report came from anywhere-agents, a toolkit that assigns work to coding assistants and collects their output. Its fix prompted us to compare the original dispatcher before and after the change. <strong>If the work was unfinished, why didn&#39;t the program handling the result catch it?</strong></p><p>This caught our attention because we are developing CodeFlowMu, a system for collaboration among AI assistants. At a handoff, the next stage needs to know whether it has a result ready for verification or output from unfinished work. This source narrowed that concern to a concrete conflict: the exit code reported success while the service response reported failure. It also supplied code before and after the fix, with tests, allowing us to investigate which decision went wrong instead of merely advising people to check results.</p><h2 id="it-found-text-but-trusted-the-wrong-success-signal" tabindex="-1">It found text, but trusted the wrong success signal <a class="header-anchor" href="#it-found-text-but-trusted-the-wrong-success-signal" aria-label="Permalink to &quot;It found text, but trusted the wrong success signal&quot;">​</a></h2><p>An AI call often passes through several programs. A dispatcher starts a command-line tool. That tool contacts the AI service and passes its response back.</p><p>When the tool exits, it returns a number called an exit code. Zero normally signals success. But if the dispatcher checks only that number, it can miss a more specific failure inside the response.</p><p>Yue Zhao&#39;s <a href="https://github.com/yzhao062/anywhere-agents/commit/3c94f459fa942727bbbf0a51ad1967d235096bc7" target="_blank" rel="noreferrer">fix</a> addresses precisely that mismatch: after hitting a quota limit, Agy could return exit code zero while its terminal event reported <code>ERROR</code> and included opening narration. The old dispatcher followed the normal-exit, nonempty-text path and wrote that narration to the result file.</p><p>Two reassuring observations hid the problem: the process had ended, and there was text to collect.</p><p>That gave us a focused experiment. Keep the exit code at zero, but supply an explicit error in the response. Can the dispatcher recognize it?</p><h2 id="give-both-versions-the-same-bad-news" tabindex="-1">Give both versions the same bad news <a class="header-anchor" href="#give-both-versions-the-same-bad-news" aria-label="Permalink to &quot;Give both versions the same bad news&quot;">​</a></h2><p>We used the project&#39;s original test tool to simulate AI responses and ran both dispatcher versions through the same scenarios. Process execution, event reading, and temporary-file writes happened locally. The AI responses came from a test double so we could control their contents.</p><p>Three cases deliberately supplied errors. Two controls checked normal success and compatibility with older response formats:</p><table tabindex="0"><thead><tr><th>Scenario supplied to the dispatcher</th><th>Does the predecessor behave as expected?</th><th>After the fix</th></tr></thead><tbody><tr><td>Exit zero, error response, opening text</td><td>No</td><td>Reports failure and leaves a fallback marker</td></tr><tr><td>Error after the worker has written a result file</td><td>No</td><td>Retains the file while reporting run failure</td></tr><tr><td>Error followed by a result message without status</td><td>No</td><td>Preserves the earlier error</td></tr><tr><td>Explicit success with result text</td><td>Yes</td><td>Still passes</td></tr><tr><td>Text without a status field</td><td>Yes, under the compatibility rule</td><td>Compatibility success is retained</td></tr></tbody></table><p>The first three tests failed on the predecessor and passed with the fix. Passing here means the program correctly acknowledges failure.</p><p>The last row matters too. The fix does not reject every older response that omits status. Explicit success and admission through a compatibility rule remain different kinds of evidence; neither should be silently described as the other.</p><p><img src="'+d+'" alt="Process outcome, provider outcome, and retained artifact"></p><p><em>Figure 1. One run can leave evidence at several levels. Source: this study&#39;s runs/dispatch.json and original test logs; provider events were simulated by the test tool.</em></p><h2 id="why-keep-a-file-from-a-failed-run" tabindex="-1">Why keep a file from a failed run? <a class="header-anchor" href="#why-keep-a-file-from-a-failed-run" aria-label="Permalink to &quot;Why keep a file from a failed run?&quot;">​</a></h2><p>The second test asks something beyond error detection. What if the assistant writes a file before the run fails?</p><p>Deleting it discards work that may still be useful. Treating it as a finished deliverable may send an incomplete result onward. The fix keeps both facts visible: the file exists, and the run failed.</p><p>Those facts can coexist. Whoever takes over has material to inspect, but still needs to establish whether it meets the request. File existence answers whether there is something to examine, not whether it is correct or complete.</p><p>The third test exposes another subtlety: the last message need not be the most informative one. If an earlier event explicitly reports failure, a later event without status should not erase it. The parser preserves the latest supplied status, error, and nonempty text separately, preventing a missing field from overwriting known information.</p><p>Both changes remove an unsupported inference from the dispatcher&#39;s decision.</p><h2 id="what-should-done-make-us-check" tabindex="-1">What should “done” make us check? <a class="header-anchor" href="#what-should-done-make-us-check" aria-label="Permalink to &quot;What should “done” make us check?&quot;">​</a></h2><p>The experiment suggests separating a broad completion claim into a few practical questions:</p><ul><li><strong>Did execution succeed?</strong> Check the AI service&#39;s reported outcome as well as the outer process exit code.</li><li><strong>What was actually produced?</strong> Opening narration, intermediate notes, and a finished result are all nonempty text.</li><li><strong>Does it meet the request?</strong> Even a successful run with a file still needs its result checked against the user&#39;s objective.</li></ul><p>For users, a completion notice followed only by “Next, I will…” is a reason to inspect further. For developers, explicit errors, leftover files, and missing status fields make useful inputs to a result-handling test.</p><p>One question remains for discussion: could downstream checks be told when a response was admitted for compatibility without an explicit success status? That is a design question prompted by the experiment, not a demonstrated new defect. Nor have these results established the same problem in CodeFlowMu. This question comes from the table&#39;s last two rows: explicit success and missing status both allow output to proceed in the tested path, but on different evidence. If downstream verification sees only a pass, can it distinguish them? A next investigation could check whether that distinction reaches the consumer and whether it should affect verification. These experiments have not answered those questions.</p><details><summary>Further reading: can checking quota prevent this failure?</summary><p>A subsequent <a href="https://github.com/yzhao062/anywhere-agents/commit/050ee0bd91c5d05c28f6f6b7c196a8d222328a4b" target="_blank" rel="noreferrer">quota-routing change</a> reads model-group quota snapshots before dispatch. An exhausted Claude/GPT group can fall back to Gemini; exhausted Gemini does not automatically switch into the scarcer group. The selected model and fallback explanation are recorded.</p><p>We ran seven original quota-policy unit tests covering the tightest bucket, nonfinite values, stale snapshots after failed refresh, reset times, unreported groups, model-name grouping, and disabling the check. All passed, alongside four helper checks. These used temporary caches and doubles, not live quota, cost, or throughput measurements.</p><p>A group absent from the snapshot may still be tried. Its capacity is unknown, not confirmed available. An early check helps choose a path, but permission to start and successful completion still require separate decisions.</p></details><p><strong>Scope and reproduction.</strong> We tested how pinned source interprets specified inputs. We did not repeat the author&#39;s historical 152-dispatch audit or exhaust a real service quota; arbitrary event reordering and replay are outside these tests. The five before/after cases, quota checks, source pins, and original logs are in the <a href="./../research/evidence/2026-09-14-continuity-contracts">evidence package</a>, maintained in the <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">research repository</a>.</p><p>Have you seen a tool report completion, only to open the result and find it still describing what it plans to do? What first alerted you? If you build these tools, how do you distinguish explicit success from compatibility admission, and does that distinction change downstream verification in practice?</p>',34))])}const v=i(c,[["render",h]]);export{w as __pageData,v as default};
